/* Build 373 MADAR icon registry. Generated by tools/madar_icons.py: edit the tool, not this file.
   Every icon is a realistic colour glyph from the inline sprite. tile(key) seats an option's glyph on a soft glass
   tile (page cards, image badges, decisions); glyph(key) draws it bare (the rail, the page strip, list rows). Frame
   controls (close, expand, alerts ...) take the button's text colour. The catalogue and saves still carry emoji in
   their data; forAsset() maps them to glyphs for display only. */
(()=>{'use strict';
const LABEL=Object.freeze({"map":"الخريطة","group":"المجموعة","finance":"المال","people":"الأفراد","leadership":"الإدارة","settings":"الحفظ والإعدادات","dashboard":"لوحة الشركة","manage":"الإدارة والهوية","company-finance":"مالية الشركة","budget":"الميزانية","deliveries":"قيد التسليم","maintenance":"الصيانة والتأمين","fleet-air":"الأسطول الجوي","buy-air":"شراء طائرات","route-air":"الخطوط الجوية","tower":"المطارات والقواعد","contract-air":"عقود الشحن الجوي","pilot":"الطواقم والأجور","fleet-sea":"الأسطول البحري","buy-sea":"شراء سفن","route-sea":"الخطوط البحرية","port":"الموانئ والقواعد","contract-sea":"عقود الشحن البحري","carbon":"تصنيف الكربون CII","captain":"الطواقم والأجور","fleet-road":"الأسطول البري","buy-road":"شراء شاحنات","route-road":"المسارات البرية","warehouse":"المستودعات والمراكز","contract-road":"عقود التوزيع","driver":"السائقون والأجور","fleet-car":"سيارات التنقل","buy-car":"شراء سيارات","route-city":"خطوط المدن","city-branch":"فروع المدن","solar":"المحطات والمشاريع","energy-dash":"لوحة الطاقة","grid":"التشغيل والتوزيع","contract-power":"العقود والتمويل","revenue":"الإيرادات","power-site":"مواقع المحطات","tender":"المناقصات والعقود","credit":"الائتمان والقروض","bank":"لوحة البنك","atm":"الفروع والخدمات","liquidity":"السيولة والمخاطر","umbrella":"لوحة التأمين","pricing":"المنتجات والتسعير","office":"المكاتب","claims":"المطالبات","house":"لوحة العقار","construction":"المشاريع","develop":"تطوير مشروع","sim":"الاشتراكات والشرائح","antenna":"الشبكة والفروع","datacenter":"نظرة الشركة","car-sales":"المخزون والمبيعات","car-service":"خطط الخدمة والتمويل","showroom":"المعارض والفروع","performance":"أداء الشركات","fleet-all":"أسطول المجموعة","directory":"الدليل العالمي","facilities":"كل المنشآت","charter":"عقد التأسيس","treasury":"الخزينة","monthly-income":"الدخل الشهري","documents":"المستندات","markets":"الأسواق والتحوط","acquisitions":"الاستحواذات","stocks":"الأسهم والطرح","people-dash":"لوحة الأفراد","executive":"المديرون التنفيذيون","jobs":"الوظائف","employment":"عقود العمل","crews":"الأجور والطواقم","payroll":"الرواتب","tasks":"المهام الآن","safety":"السلامة والأمن","conference":"المؤتمر السنوي","research":"البحث والتطوير","esg":"الاستدامة","relations":"العلاقات التجارية","economy":"السوق والاقتصاد","news":"الأخبار","updates":"التحديثات","diagnostics":"صحة اللعبة","control-plane":"مركز التحكم","routes":"الخطوط والمسارات","market":"سوق الأصول","contracts":"العقود","asset":"بطاقة الأصل","bell":"التنبيهات","layers":"طبقات الخريطة","ticker":"شريط الأخبار","close":"إغلاق","expand":"فتح القسم بالكامل","collapse":"تصغير القسم","back":"رجوع","add":"إضافة","bolt":"الطاقة"});
const CONTROLS=Object.freeze(["add","back","bell","close","collapse","expand","layers","ticker"]);
const EMOJI=Object.freeze({"✈️":"fleet-air","✈":"fleet-air","🚢":"fleet-sea","🛳️":"fleet-sea","🚛":"fleet-road","🚚":"fleet-road","🚙":"fleet-car","🚗":"fleet-car","🚕":"fleet-car","🚘":"fleet-car","🚖":"fleet-car","🚐":"fleet-car","⚡":"bolt","🏦":"bank","🏢":"office","🏛️":"group","⚓":"port","🛫":"tower","🛠️":"maintenance","🛠":"maintenance","🔧":"maintenance","🔩":"maintenance","👨‍✈️":"pilot","👩‍✈️":"pilot","🧑‍✈️":"captain"});
const TYPE=Object.freeze({air:'fleet-air',sea:'fleet-sea',road:'fleet-road',mobility:'fleet-car'});
const known=key=>Object.prototype.hasOwnProperty.call(LABEL,key);
const pick=key=>known(key)?key:'group';
const classes=extra=>String(extra||'').replace(/[^a-z0-9 -]/gi,'').trim();
function glyph(key,extra=''){const id=pick(key),more=classes(extra);return `<svg class="mg${more?` ${more}`:''}" data-icon="${id}" aria-hidden="true" focusable="false"><use href="#m-${id}"></use></svg>`;}
function tile(key,extra=''){const id=pick(key),more=classes(extra);if(CONTROLS.includes(id))return glyph(id,extra);return `<span class="mi${more?` ${more}`:''}" data-icon="${id}" aria-hidden="true"><svg class="mi-g" focusable="false"><use href="#m-${id}"></use></svg></span>`;}
function forAsset(icon,type){return EMOJI[String(icon||'')]||TYPE[String(type||'')]||null;}
function inline(icon,type,fallback='facilities'){return glyph(forAsset(icon,type)||fallback,'mg-inline');}
globalThis.GH_ICONS=Object.freeze({VERSION:'373.2',LABEL,CONTROLS,has:known,glyph,tile,forAsset,inline});
})();
